const{DatabaseSync}=require('node:sqlite');
const db=new DatabaseSync('.codegraph/codegraph.db');
// candidate persistent entity types: struct nodes defined directly in top-level 'store/' package (not subdirs)
const types=db.prepare(\`
  SELECT id,name,file_path,start_line FROM nodes
  WHERE kind='struct' AND file_path LIKE 'store/%.go' AND file_path NOT LIKE 'store/db/%'
    AND file_path NOT LIKE 'store/cache/%' AND file_path NOT LIKE 'store/test/%'
    AND file_path NOT LIKE '%_test.go'
\`).all();
function pkg(fp){const i=fp.lastIndexOf('/');return i<0?'.':fp.slice(0,i);}
const out=[];
const seen=new Set();
for(const t of types){
  // inbound reference+instantiates edges
  const rows=db.prepare(\"SELECT DISTINCT s.file_path AS fp FROM edges e JOIN nodes s ON s.id=e.source WHERE e.target=? AND e.kind IN ('references','instantiates')\").all(t.id);
  const pkgs=new Set();
  for(const r of rows){const p=pkg(r.fp); if(!p.startsWith('store')) pkgs.add(p);}
  out.push({name:t.name,fp:t.file_path+':'+t.start_line,ext:pkgs.size,pkgs:[...pkgs]});
}
// entity types often have same name across; aggregate by name keeping max
out.sort((a,b)=>b.ext-a.ext);
for(const o of out.slice(0,15)) console.log(o.ext+'  '+o.name+'  ('+o.fp+')');
" 2>/dev/null

